import{z as p,x as d,o as l,c as A,q as n,j as i,D as t,d as o,s as r,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"节点受限路由","description":"","frontmatter":{"title":"节点受限路由","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/node-limited-routing.md","filePath":"llm/node-limited-routing.md","lastUpdated":1791413859000}'),B={name:"llm/node-limited-routing.md"};function m(k,e,h,M,u,c){const E=d("Mermaid");return l(),A("div",null,[e[2]||(e[2]=n('<h1 id="节点受限路由" tabindex="-1">节点受限路由 <a class="header-anchor" href="#节点受限路由" aria-label="Permalink to &quot;节点受限路由&quot;">​</a></h1><div class="epigraph"><p>每个 token 只允许从少数设备上的专家里选，把 All-to-All 的扇出从「全球」收到「几台邻居」。</p><footer>—— DeepSeek-V2 的 device-limited routing；大规模稀疏通信的背景见 Lepikhin et al., GShard, 2020</footer></div><p><a href="/llm/aux-loss-free-balancing">上一课</a>让负载在<strong>全局专家集</strong>上调偏置。真正训练时专家铺在许多节点上，token 选中远端专家就要跨机搬隐状态。<a href="/llm/moe-routing">GShard</a> 已经付 All-to-All。本课补硬约束：每个 token 先限定候选节点数 \\(M\\)，再在这些节点的专家里 top-\\(k\\)。后课序列级均衡在这张被剪过的候选图上做；通信比课会算 \\(M\\) 怎么进公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>专家数 \\(N\\) 到上百、上千时，无约束 top-\\(k\\) 的通信对象几乎是全部设备：每个 token 一份向量飞向 \\(k\\) 台可能很远的机器，网络先于计算饱和。缺口是<strong>限制扇出</strong>：不是改专家内部，而是改可选集合的拓扑。DeepSeek-V2 的 device-limited routing 让每个 token 最多与 \\(M\\) 个设备通信（\\(M\\) 常为 1 或 2 量级的小整数）。</p><p>这与容量因子不同：容量是设备上专家能吃多少 token；节点受限是 token 能跟几台设备说话。两者叠加。</p><p><span class="marginnote">节点（device）不是专家。一台设备可挂多名专家。限制的是设备数，设备内专家仍可再 top。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先对专家打分，再按设备聚合（取设备上专家的最大分或分数和），选出 \\(M\\) 台设备，然后只在这些设备的专家里做 top-\\(k\\)。\\(k\\) 仍可大于 \\(M\\) 若每设备多专家。实现上 All-to-All 的对端集合变小，或改成对 \\(M\\) 个目标的点对点/分组通信。</p><p><span class="marginnote">直觉类比：像深夜点外卖不搜全城，而是先圈定最近的两三家商场（选 \\(M\\) 台设备），再只在商场里挑店（设备内 top-\\(k\\)）。全城搜得到更多好店，但配送范围爆炸；圈商圈省的是「跑腿」，代价是菜单变短。</span></p><p>偏置均衡仍可做，但统计负载时要承认：有些专家对某些 token 根本不可见，均匀是在「可见性图」上的均匀，不是全局均匀。哈希也可以先哈希到节点再哈希到专家，天然节点受限。</p><h3 id="与专家并行布局" tabindex="-1">与专家并行布局 <a class="header-anchor" href="#与专家并行布局" aria-label="Permalink to &quot;与专家并行布局&quot;">​</a></h3><p>专家在设备上的摆放决定图的品质。同一类专家挤在一台机器上，token 一旦选中这台就能拿全套；打散则 \\(M\\) 小会切掉组合。EPLB 一类放置算法（主干若已有 <a href="/llm/eplb">EPLB</a>）与本课正交：本课是路由约束，放置是布局。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(M=1\\) 时 token 先选机柜再选专家，通信接近一次机内 GEMM 加一次跨机，扇出最小，表达力最伤：永远看不见其它机器上的专家。\\(M\\) 增大，向无约束 top-\\(k\\) 连续过渡。训练应把 \\(M\\) 当架构超参固定，与推理一致，否则训练时看见的专家集比推理大，质量虚高。\\(M\\) 还可以随训练进度放开：早期 \\(M\\) 大以便探索，后期收到部署值——必须把后期值当作真正架构，早期只是优化技巧。</p>',15)),(l(),i(s,null,{default:t(()=>[r(E,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20M1%5B%22M%3D1%22%5D%20--%3E%7C%22%E9%80%9A%E4%BF%A1%E4%BE%A7%22%7C%20C1%5B%22%E5%AF%B9%E7%AB%AF%E4%BB%85%E4%B8%80%E5%8F%B0%E6%9C%BA%20%E6%89%87%E5%87%BA%E6%9C%80%E5%B0%8F%22%5D%0A%20%20M1%20--%3E%7C%22%E8%A1%A8%E8%BE%BE%E4%BE%A7%22%7C%20L1%5B%22%E5%85%B6%E5%AE%83%E6%9C%BA%E5%99%A8%E7%9A%84%E4%B8%93%E5%AE%B6%E6%B0%B8%E4%B8%8D%E5%8F%AF%E8%A7%81%22%5D%0A%20%20MBIG%5B%22M%20%E5%A2%9E%E5%A4%A7%22%5D%20--%3E%7C%22%E9%80%9A%E4%BF%A1%E4%BE%A7%22%7C%20C2%5B%22%E6%89%87%E5%87%BA%E4%B8%8A%E5%8D%87%20%E8%B6%8B%E5%90%91%E6%97%A0%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20MBIG%20--%3E%7C%22%E8%A1%A8%E8%BE%BE%E4%BE%A7%22%7C%20L2%5B%22%E5%8F%AF%E8%A7%81%E4%B8%93%E5%AE%B6%E7%BB%84%E5%90%88%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n('<p>这张图回答「\\(M\\) 这个旋钮拧的是什么」：每拧一格都在通信成本与专家组合表达力之间做交换，\\(M=1\\) 与无约束 top-\\(k\\) 是谱系两端。它不是「更省的等价实现」，而是换了一个模型。</p><p>节点受限会诱导「设备级特化」：某台机器上的专家共同服务一类 token，因为它们总是一起被看见。这与后课层次 MoE 的显式层级不同，但是同一种可见性造成的聚类。</p><p><span class="marginnote">过小的 \\(M\\) 加尖锐门，等于把模型切成 \\(M\\) 台近乎独立的稠密模型，稀疏参数的组合优势消失。</span></p><p><span class="marginnote">为什么重要：训练用 \\(M=8\\)、部署用 \\(M=1\\)，等于考试开卷、上岗闭卷——评测分是虚的，上线才掉分。\\(M\\) 是架构参数，定了部署值就该让训练过程收敛到它，早期放开只当探索技巧。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单机或专家很少时本课无意义，不要加约束自找特化损失。网络拓扑（NVLink 域、机柜）应与 \\(M\\) 对齐：限的「节点」最好是通信便宜的单元。下一课序列级均衡处理的是另一轴——一条序列内部专家占用，不是机器扇出。通信-计算比课会把 \\(M\\)、\\(k\\)、\\(d\\) 放进同一条粗公式。</p><p><span class="marginnote">数字实例：256 名专家铺在 32 台设备上，每台 8 名。无约束 top-8 时一个 token 最多要跟 8 台机器通信；\\(M=1\\) 后只跟 1 台，跨机消息目标数降到原先的 \\(1/8\\) 以内——\\(k\\) 仍是 8，只是 8 名专家都从同一台机器里出。</span></p>',7)),(l(),i(s,null,{default:t(()=>[r(E,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20Scores%5B%22%E5%85%A8%E5%B1%80%E4%B8%93%E5%AE%B6%E5%88%86%E6%95%B0%22%5D%20--%3E%20Dev%5B%22%E8%81%9A%E5%90%88%E6%88%90%E8%AE%BE%E5%A4%87%E5%88%86%22%5D%0A%20%20Dev%20--%3E%20Pick%5B%22%E9%80%89%20M%20%E5%8F%B0%E8%AE%BE%E5%A4%87%22%5D%0A%20%20Pick%20--%3E%20Local%5B%22%E4%BB%85%E5%9C%A8%E5%80%99%E9%80%89%E8%AE%BE%E5%A4%87%E5%86%85%20top-k%22%5D%0A%20%20Local%20--%3E%20Comm%5B%22%E6%89%87%E5%87%BA%E4%B8%8D%E8%B6%85%E8%BF%87%20M%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a("h2",{id:"小结",tabindex:"-1"},[o("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[5]||(e[5]=a("ul",null,[a("li",null,"节点受限路由把每个 token 的通信对端收到 \\(M\\) 台设备，再在内部选专家。"),a("li",null,"负载均匀与特化都变成可见性图上的性质，不是全局集合上的。"),a("li",null,"\\(M\\) 必须训推一致；过小则稀疏组合名存实亡。"),a("li",null,"与容量因子、专家放置正交，三者一起决定能否训练。"),a("li",null,"出处：DeepSeek-V2 的 device-limited routing；GShard, 2020。")],-1))])}const _=p(B,[["render",m]]);export{D as __pageData,_ as default};
